-- ------------------------------------------------------------------
-- The moonkin form
-- ------------------------------------------------------------------
-- The script hooks onto the NATIVE moonkin form spell, whose first effect carries
-- SPELL_AURA_MOD_SHAPESHIFT. The generator only names our own spells, so the
-- binding lives here.

DELETE FROM `spell_script_names`
    WHERE `spell_id` = 24858 AND `ScriptName` = 'spell_spheregrid_moonkin_form';
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`)
VALUES (24858, 'spell_spheregrid_moonkin_form');

-- ------------------------------------------------------------------
-- The gauge auras
-- ------------------------------------------------------------------
-- The gauge auras must never be saved: Aura::CanBeSaved reads this custom
-- attribute, which is loaded at server startup.
-- (2026-09-06).
--
-- SPELL_ATTR0_CU_AURA_CANNOT_BE_SAVED (0x01000000, spell_custom_attr) :
--   85129 Solstice, 85130 Equinoxe (bouts atteints, 6 s)
--   85132 Jauge lunaire, 85133 Jauge solaire (piles)
--   85134 Soleil epuise, 85135 Lune epuisee (verrous)
DELETE FROM `spell_custom_attr` WHERE `spell_id` BETWEEN 85129 AND 85135;
INSERT INTO `spell_custom_attr` (`spell_id`, `attributes`) VALUES
(85129, 0x01000000), (85130, 0x01000000), (85131, 0x01000000),
(85132, 0x01000000), (85133, 0x01000000), (85134, 0x01000000),
(85135, 0x01000000);

-- Translations: German, Spanish, Russian, in the columns the client reads for each language
-- (see THE LANGUAGE SLOT above): German in `_Lang_frFR`, Spanish in `_Lang_zhCN`,
-- Russian in `_Lang_zhTW`. An aura text longer than its varchar(550) column is left out: the
-- server never shows it, and the client reads the whole text from its own Spell.dbc.
