UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Rune der Heilung', `Name_Lang_zhCN` = 'Runa de sanación', `Name_Lang_zhTW` = 'Руна исцеления', `Description_Lang_frFR` = 'Erhöht die von Eurem Sphärobrett gewährte Heilung um 10%. Höchstens drei pro Wert. Im Sphärobrett anzuwenden.', `Description_Lang_zhCN` = 'Aumenta un 10% lo que tu Tablero de esferas otorga en sanación. Tres como máximo por estadística. Aplícala en el Tablero de esferas.', `Description_Lang_zhTW` = 'Увеличивает на 10% прибавку к исцелению, которую дает ваша Сферическая сетка. Не более трех на одну характеристику. Применяется в Сферической сетке.' WHERE `ID` = 85915;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Heldenhafter Sprung', `Name_Lang_zhCN` = 'Salto heroico', `Name_Lang_zhTW` = 'Геройский прыжок', `Description_Lang_frFR` = 'Springt zur anvisierten Stelle und verursacht bei der Landung ${$m2+$AP*0.125} Schaden.', `Description_Lang_zhCN` = 'Saltas al punto seleccionado e infliges ${$m2+$AP*0.125} p. de daño al aterrizar.', `Description_Lang_zhTW` = 'Вы прыгаете в указанную точку и при приземлении наносите ${$m2+$AP*0.125} ед. урона.', `AuraDescription_Lang_frFR` = 'Springt zur anvisierten Stelle und verursacht bei der Landung ${$m2+$AP*0.125} Schaden.', `AuraDescription_Lang_zhCN` = 'Saltas al punto seleccionado e infliges ${$m2+$AP*0.125} p. de daño al aterrizar.', `AuraDescription_Lang_zhTW` = 'Вы прыгаете в указанную точку и при приземлении наносите ${$m2+$AP*0.125} ед. урона.' WHERE `ID` = 85000;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Weitreichende Stöße', `Name_Lang_zhCN` = 'Golpes de barrido', `Name_Lang_zhTW` = 'Размашистые удары', `Description_Lang_frFR` = '$d lang trifft jeder Nahkampfschlag zusätzlich einen zweiten Feind in der Nähe oder, falls keiner in Reichweite ist, erneut dasselbe Ziel.', `Description_Lang_zhCN` = 'Durante $d, cada golpe cuerpo a cuerpo alcanza también a un segundo enemigo cercano, o de nuevo al mismo objetivo si no hay ninguno al alcance.', `Description_Lang_zhTW` = 'В течение $d. каждый ваш удар в ближнем бою также поражает второго находящегося поблизости противника или повторно ту же цель, если рядом никого нет.', `AuraDescription_Lang_frFR` = 'Nahkampfschläge treffen ein zusätzliches Ziel.', `AuraDescription_Lang_zhCN` = 'Los golpes cuerpo a cuerpo alcanzan a un objetivo adicional.', `AuraDescription_Lang_zhTW` = 'Удары в ближнем бою поражают дополнительную цель.' WHERE `ID` = 85001;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Aufspießen', `Name_Lang_zhCN` = 'Empalamiento', `Name_Lang_zhTW` = 'Пронзание', `Description_Lang_frFR` = 'Trifft alle Feinde vor Euch für ${$m1+$AP*0.1886} Schaden und lässt sie $d lang bluten, wodurch sie pro Sekunde ${$m2+$AP*0.1234} Schaden erleiden.', `Description_Lang_zhCN` = 'Golpea a todos los enemigos que tienes delante, les inflige ${$m1+$AP*0.1886} p. de daño y los deja sangrando, lo que les inflige ${$m2+$AP*0.1234} p. de daño por segundo durante $d.', `Description_Lang_zhTW` = 'Наносит всем противникам перед вами ${$m1+$AP*0.1886} ед. урона и вызывает у них кровотечение, наносящее ${$m2+$AP*0.1234} ед. урона в секунду в течение $d.', `AuraDescription_Lang_frFR` = 'Blutet. Erleidet pro Sekunde ${$m2+$AP*0.1234} Schaden.', `AuraDescription_Lang_zhCN` = 'Sangrando. Recibe ${$m2+$AP*0.1234} p. de daño por segundo.', `AuraDescription_Lang_zhTW` = 'Кровотечение. ${$m2+$AP*0.1234} ед. урона в секунду.' WHERE `ID` = 85002;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Spartanischer Schild', `Name_Lang_zhCN` = 'Escudo espartano', `Name_Lang_zhTW` = 'Спартанский щит', `Description_Lang_frFR` = 'Errichtet eine Barriere, die $s1 Schaden absorbiert und mit jedem ausgegebenen Wutpunkt, Eurem Blockwert und Eurer Rüstung größer wird.', `Description_Lang_zhCN` = 'Alza una barrera que absorbe $s1 p. de daño, cantidad que aumenta con cada punto de ira gastado, con tu valor de bloqueo y con tu armadura.', `Description_Lang_zhTW` = 'Создает барьер, поглощающий $s1 ед. урона. Чем больше потрачено ярости и чем выше показатель блокирования и ваша броня, тем прочнее барьер.', `AuraDescription_Lang_frFR` = 'Errichtet eine Barriere, die $s1 Schaden absorbiert und mit jedem ausgegebenen Wutpunkt, Eurem Blockwert und Eurer Rüstung größer wird.', `AuraDescription_Lang_zhCN` = 'Alza una barrera que absorbe $s1 p. de daño, cantidad que aumenta con cada punto de ira gastado, con tu valor de bloqueo y con tu armadura.', `AuraDescription_Lang_zhTW` = 'Создает барьер, поглощающий $s1 ед. урона. Чем больше потрачено ярости и чем выше показатель блокирования и ваша броня, тем прочнее барьер.' WHERE `ID` = 85003;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Göttliches Ross', `Name_Lang_zhCN` = 'Corcel divino', `Name_Lang_zhTW` = 'Божественный скакун', `Description_Lang_frFR` = 'Ihr bewegt Euch $d lang $s1% schneller, auf einem göttlichen Ross reitend.', `Description_Lang_zhCN` = 'Te mueves un $s1% más rápido durante $d a lomos de un corcel divino.', `Description_Lang_zhTW` = 'Верхом на божественном скакуне вы передвигаетесь на $s1% быстрее в течение $d.', `AuraDescription_Lang_frFR` = 'Reitet auf einem göttlichen Ross.', `AuraDescription_Lang_zhCN` = 'A lomos de un corcel divino.', `AuraDescription_Lang_zhTW` = 'Верхом на божественном скакуне.' WHERE `ID` = 85010;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Letzte Abrechnung', `Name_Lang_zhCN` = 'Ajuste de cuentas final', `Name_Lang_zhTW` = 'Последняя расплата', `Description_Lang_frFR` = 'Schmettert mit ${$m1+$SPH*0.4141+$AP*0.2852} Schaden auf den Boden und markiert ihn: Feinde dort erleiden $d lang $s2% mehr Schaden.', `Description_Lang_zhCN` = 'Golpea el suelo, inflige ${$m1+$SPH*0.4141+$AP*0.2852} p. de daño y lo marca: los enemigos que se encuentren en él reciben un $s2% más de daño durante $d.', `Description_Lang_zhTW` = 'Наносит удар по земле, причиняя ${$m1+$SPH*0.4141+$AP*0.2852} ед. урона, и помечает это место: находящиеся там противники получают на $s2% больше урона в течение $d.', `AuraDescription_Lang_frFR` = 'Erleidet $s2% mehr Schaden.', `AuraDescription_Lang_zhCN` = 'Recibe un $s2% más de daño.', `AuraDescription_Lang_zhTW` = 'Получаемый урон увеличен на $s2%.' WHERE `ID` = 85011;
