UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Aspekt des Jaguars', `Name_Lang_zhCN` = 'Aspecto del jaguar', `Name_Lang_zhTW` = 'Дух ягуара', `Description_Lang_frFR` = 'Ihr und Verbündete in der Nähe erhaltet $d lang $s1% Tempo.', `Description_Lang_zhCN` = 'Tú y los aliados cercanos ganáis un $s1% de velocidad durante $d.', `Description_Lang_zhTW` = 'Скорость передвижения ваша и находящихся поблизости союзников повышается на $s1% на $d.', `AuraDescription_Lang_frFR` = 'Ihr und Verbündete in der Nähe erhaltet $d lang $s1% Tempo.', `AuraDescription_Lang_zhCN` = 'Tú y los aliados cercanos ganáis un $s1% de velocidad durante $d.', `AuraDescription_Lang_zhTW` = 'Скорость передвижения ваша и находящихся поблизости союзников повышается на $s1% на $d.' WHERE `ID` = 85020;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Stampede', `Name_Lang_zhCN` = 'Estampida', `Name_Lang_zhTW` = 'Паническое бегство', `Description_Lang_frFR` = 'Euer Stall bricht hervor: Alle Eure Tiere stürmen $d lang los.', `Description_Lang_zhCN` = 'Tu establo irrumpe: todas tus bestias cargan durante $d.', `Description_Lang_zhTW` = 'Ваше стойло вырывается на волю: все ваши звери бросаются в атаку на $d.', `AuraDescription_Lang_frFR` = 'Euer Stall bricht hervor: Alle Eure Tiere stürmen $d lang los.', `AuraDescription_Lang_zhCN` = 'Tu establo irrumpe: todas tus bestias cargan durante $d.', `AuraDescription_Lang_zhTW` = 'Ваше стойло вырывается на волю: все ваши звери бросаются в атаку на $d.' WHERE `ID` = 85021;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Folgeschüsse', `Name_Lang_zhCN` = 'Disparos consecutivos', `Name_Lang_zhTW` = 'Последовательные выстрелы', `Description_Lang_frFR` = 'Kanalisiert $d lang eine Salve durchbohrender Schüsse. Jeder Schuss bleibt $85096d lang im Ziel stecken. Das Ziel explodiert nach 6 Sek. und fügt allen Feinden innerhalb von $85098a1 Metern Schaden abhängig von der Anzahl der Pfeile zu.', `Description_Lang_zhCN` = 'Canaliza una salva de disparos perforantes durante $d. Cada disparo se queda clavado en el objetivo durante $85096d. El objetivo explota al cabo de 6 s e inflige daño en función del número de flechas a todos los enemigos en un radio de $85098a1 m.', `Description_Lang_zhTW` = 'В течение $d. вы выпускаете залп пронзающих выстрелов. Каждая стрела застревает в цели на $85096d. Через 6 сек. цель взрывается, нанося всем противникам в радиусе $85098a1 м урон, зависящий от количества застрявших стрел.', `AuraDescription_Lang_frFR` = 'Kanalisiert $d lang eine Salve durchbohrender Schüsse. Jeder Schuss bleibt $85096d lang im Ziel stecken. Das Ziel explodiert nach 6 Sek. und fügt allen Feinden innerhalb von $85098a1 Metern Schaden abhängig von der Anzahl der Pfeile zu.', `AuraDescription_Lang_zhCN` = 'Canaliza una salva de disparos perforantes durante $d. Cada disparo se queda clavado en el objetivo durante $85096d. El objetivo explota al cabo de 6 s e inflige daño en función del número de flechas a todos los enemigos en un radio de $85098a1 m.', `AuraDescription_Lang_zhTW` = 'В течение $d. вы выпускаете залп пронзающих выстрелов. Каждая стрела застревает в цели на $85096d. Через 6 сек. цель взрывается, нанося всем противникам в радиусе $85098a1 м урон, зависящий от количества застрявших стрел.' WHERE `ID` = 85022;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Wildfeuerbombe', `Name_Lang_zhCN` = 'Bomba de fuego salvaje', `Name_Lang_zhTW` = 'Зажигательная бомба', `Description_Lang_frFR` = 'Schleudert eine Bombe, die ${$m1+$RAP*0.11} Schaden verursacht und den Boden $d lang in Brand setzt.', `Description_Lang_zhCN` = 'Lanza una bomba que inflige ${$m1+$RAP*0.11} p. de daño y prende fuego al suelo durante $d.', `Description_Lang_zhTW` = 'Бросает бомбу, которая наносит ${$m1+$RAP*0.11} ед. урона и поджигает землю на $d.', `AuraDescription_Lang_frFR` = 'Schleudert eine Bombe, die ${$m1+$RAP*0.11} Schaden verursacht und den Boden $d lang in Brand setzt.', `AuraDescription_Lang_zhCN` = 'Lanza una bomba que inflige ${$m1+$RAP*0.11} p. de daño y prende fuego al suelo durante $d.', `AuraDescription_Lang_zhTW` = 'Бросает бомбу, которая наносит ${$m1+$RAP*0.11} ед. урона и поджигает землю на $d.' WHERE `ID` = 85023;
