UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Königsfluch', `Name_Lang_zhCN` = 'Perdición de reyes', `Name_Lang_zhTW` = 'Погибель королей', `Description_Lang_frFR` = 'Stößt eine vergiftete Klinge in das Ziel, die im Verlauf von $d ${$m1+$AP*0.2} Schaden verursacht. Der Schaden ist pro Gift auf dem Ziel um 25% erhöht.', `Description_Lang_zhCN` = 'Clava una hoja envenenada que inflige ${$m1+$AP*0.2} p. de daño durante $d. El daño aumenta un 25% por cada veneno en el objetivo.', `Description_Lang_zhTW` = 'Вонзает в цель отравленный клинок, нанося ${$m1+$AP*0.2} ед. урона в течение $d. Урон увеличивается на 25% за каждый яд на цели.', `AuraDescription_Lang_frFR` = 'Schaden pro Gift auf dem Ziel um 25% erhöht.', `AuraDescription_Lang_zhCN` = 'Daño aumentado un 25% por cada veneno en el objetivo.', `AuraDescription_Lang_zhTW` = 'Урон увеличивается на 25% за каждый яд на цели.' WHERE `ID` = 85031;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Knochenwürfel', `Name_Lang_zhCN` = 'Tirar los huesos', `Name_Lang_zhTW` = 'Бросок костей', `Description_Lang_frFR` = 'Finishing Move, der mit den Knochen würfelt und zufällige Vorteile gewährt. Anzahl und Dauer hängen von den Combopunkten ab:\n\n   1 Punkt  : 1 Vorteil für 15 Sek.\n\n   2 Punkte: 1 Vorteil für 30 Sek.\n\n   3 Punkte: 2 Vorteile für 15 Sek.\n\n   4 Punkte: 2 Vorteile für 30 Sek.\n\n   5 Punkte: 3 Vorteile für 15 Sek.', `Description_Lang_zhCN` = 'Movimiento final que tira los huesos y otorga bonificaciones aleatorias. La cantidad y la duración dependen de los puntos de combo:\n\n   1 punto: 1 bonificación durante 15 s\n\n   2 puntos: 1 bonificación durante 30 s\n\n   3 puntos: 2 bonificaciones durante 15 s\n\n   4 puntos: 2 bonificaciones durante 30 s\n\n   5 puntos: 3 bonificaciones durante 15 s', `Description_Lang_zhTW` = 'Завершающий прием: вы бросаете кости и получаете случайные преимущества. Их количество и время действия зависят от длины серии приемов:\n\n   1 прием: 1 преимущество на 15 сек.\n\n   2 приема: 1 преимущество на 30 сек.\n\n   3 приема: 2 преимущества на 15 сек.\n\n   4 приема: 2 преимущества на 30 сек.\n\n   5 приемов: 3 преимущества на 15 сек.', `AuraDescription_Lang_frFR` = 'Finishing Move, der mit den Knochen würfelt und zufällige Vorteile gewährt. Anzahl und Dauer hängen von den Combopunkten ab:\n\n   1 Punkt  : 1 Vorteil für 15 Sek.\n\n   2 Punkte: 1 Vorteil für 30 Sek.\n\n   3 Punkte: 2 Vorteile für 15 Sek.\n\n   4 Punkte: 2 Vorteile für 30 Sek.\n\n   5 Punkte: 3 Vorteile für 15 Sek.', `AuraDescription_Lang_zhCN` = 'Movimiento final que tira los huesos y otorga bonificaciones aleatorias. La cantidad y la duración dependen de los puntos de combo:\n\n   1 punto: 1 bonificación durante 15 s\n\n   2 puntos: 1 bonificación durante 30 s\n\n   3 puntos: 2 bonificaciones durante 15 s\n\n   4 puntos: 2 bonificaciones durante 30 s\n\n   5 puntos: 3 bonificaciones durante 15 s', `AuraDescription_Lang_zhTW` = 'Завершающий прием: вы бросаете кости и получаете случайные преимущества. Их количество и время действия зависят от длины серии приемов:\n\n   1 прием: 1 преимущество на 15 сек.\n\n   2 приема: 1 преимущество на 30 сек.\n\n   3 приема: 2 преимущества на 15 сек.\n\n   4 приема: 2 преимущества на 30 сек.\n\n   5 приемов: 3 преимущества на 15 сек.' WHERE `ID` = 85032;
