UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Symbole des Todes', `Name_Lang_zhCN` = 'Símbolos de muerte', `Name_Lang_zhTW` = 'Символы смерти', `Description_Lang_frFR` = 'Markiert das Ziel: Es erleidet $d lang $s1% mehr Schaden durch EUCH, und $s2 Energie strömt zu Euch zurück.', `Description_Lang_zhCN` = 'Marca al objetivo: recibe un $s1% más de daño de TU parte durante $d y recuperas de golpe $s2 p. de energía.', `Description_Lang_zhTW` = 'Помечает цель: в течение $d. она получает на $s1% больше урона от ВАС, а к вам возвращается $s2 ед. энергии.', `AuraDescription_Lang_frFR` = 'Erleidet $s1% mehr Schaden durch den Schurken, der es markiert hat.', `AuraDescription_Lang_zhCN` = 'Recibe un $s1% más de daño del pícaro que lo marcó.', `AuraDescription_Lang_zhTW` = 'Получает на $s1% больше урона от разбойника, оставившего метку.' WHERE `ID` = 85033;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Engelsfeder', `Name_Lang_zhCN` = 'Pluma angelical', `Name_Lang_zhTW` = 'Ангельское перо', `Description_Lang_frFR` = 'Platziert 6 Sek. lang eine Feder; der erste Verbündete, der sie überquert, erhält $85097d lang $85097s1% Tempo. Hält drei Federn bereit.', `Description_Lang_zhCN` = 'Coloca una pluma durante 6 s; el primer aliado que la cruce gana un $85097s1% de velocidad durante $85097d. Almacena hasta tres plumas.', `Description_Lang_zhTW` = 'Помещает на землю перо на 6 сек. Скорость передвижения первого союзника, который пройдет через него, повышается на $85097s1% на $85097d. В запасе может быть до трех перьев.', `AuraDescription_Lang_frFR` = 'Platziert 6 Sek. lang eine Feder; der erste Verbündete, der sie überquert, erhält $85097d lang $85097s1% Tempo. Hält drei Federn bereit.', `AuraDescription_Lang_zhCN` = 'Coloca una pluma durante 6 s; el primer aliado que la cruce gana un $85097s1% de velocidad durante $85097d. Almacena hasta tres plumas.', `AuraDescription_Lang_zhTW` = 'Помещает на землю перо на 6 сек. Скорость передвижения первого союзника, который пройдет через него, повышается на $85097s1% на $85097d. В запасе может быть до трех перьев.' WHERE `ID` = 85040;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Schattenwort: Verzweiflung', `Name_Lang_zhCN` = 'Palabra de las Sombras: desesperación', `Name_Lang_zhTW` = 'Слово Тьмы: Отчаяние', `Description_Lang_frFR` = 'Verursacht in einem Gebiet ${$m1+$SPS*0.3143} bis ${$M1+$SPS*0.3143} Schaden; die Opfer erleiden zudem ''Schattenwort: Schmerz'' und ''Vampirberührung''.', `Description_Lang_zhCN` = 'Inflige de ${$m1+$SPS*0.3143} a ${$M1+$SPS*0.3143} p. de daño en un área; las víctimas también sufren Palabra de las Sombras: dolor y Toque vampírico.', `Description_Lang_zhTW` = 'Наносит от ${$m1+$SPS*0.3143} до ${$M1+$SPS*0.3143} ед. урона в области действия. Кроме того, жертвы попадают под действие заклинаний "Слово Тьмы: Боль" и "Прикосновение вампира".', `AuraDescription_Lang_frFR` = 'Verursacht in einem Gebiet ${$m1+$SPS*0.3143} bis ${$M1+$SPS*0.3143} Schaden; die Opfer erleiden zudem ''Schattenwort: Schmerz'' und ''Vampirberührung''.', `AuraDescription_Lang_zhCN` = 'Inflige de ${$m1+$SPS*0.3143} a ${$M1+$SPS*0.3143} p. de daño en un área; las víctimas también sufren Palabra de las Sombras: dolor y Toque vampírico.', `AuraDescription_Lang_zhTW` = 'Наносит от ${$m1+$SPS*0.3143} до ${$M1+$SPS*0.3143} ед. урона в области действия. Кроме того, жертвы попадают под действие заклинаний "Слово Тьмы: Боль" и "Прикосновение вампира".' WHERE `ID` = 85041;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Machtwort: Barriere', `Name_Lang_zhCN` = 'Palabra de poder: barrera', `Name_Lang_zhTW` = 'Слово силы: Барьер', `Description_Lang_frFR` = 'Errichtet $d lang eine Kuppel: Verbündete darunter erleiden $85059s1% weniger körperlichen Schaden. Die Kuppel schrumpft beim Verblassen auf die Hälfte ihrer Größe.', `Description_Lang_zhCN` = 'Alza una cúpula durante $d: los aliados que se encuentren bajo ella reciben un $85059s1% menos de daño físico. La cúpula se reduce hasta la mitad de su tamaño a medida que se debilita.', `Description_Lang_zhTW` = 'Создает купол на $d.: союзники под ним получают на $85059s1% меньше физического урона. По мере угасания купол сжимается вдвое.', `AuraDescription_Lang_frFR` = 'Errichtet $d lang eine Kuppel: Verbündete darunter erleiden $85059s1% weniger körperlichen Schaden. Die Kuppel schrumpft beim Verblassen auf die Hälfte ihrer Größe.', `AuraDescription_Lang_zhCN` = 'Alza una cúpula durante $d: los aliados que se encuentren bajo ella reciben un $85059s1% menos de daño físico. La cúpula se reduce hasta la mitad de su tamaño a medida que se debilita.', `AuraDescription_Lang_zhTW` = 'Создает купол на $d.: союзники под ним получают на $85059s1% меньше физического урона. По мере угасания купол сжимается вдвое.' WHERE `ID` = 85042;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Strahlenkranz', `Name_Lang_zhCN` = 'Halo', `Name_Lang_zhTW` = 'Сияние', `Description_Lang_frFR` = 'Ein Ring aus Licht breitet sich aus und zieht sich dann wieder zusammen: Jeder Durchgang heilt Verbündete um ${$85045m1+$SPH*0.8863} und versengt Feinde für ${$85044m1+$SPH*1.2} bis ${$85044M1+$SPH*1.2} Schaden.', `Description_Lang_zhCN` = 'Un anillo de luz se expande y luego se contrae: cada pasada sana ${$85045m1+$SPH*0.8863} p. a los aliados y abrasa a los enemigos, a los que inflige de ${$85044m1+$SPH*1.2} a ${$85044M1+$SPH*1.2} p. de daño.', `Description_Lang_zhTW` = 'Кольцо света расходится во все стороны, а затем сжимается обратно: при каждом прохождении оно восстанавливает союзникам ${$85045m1+$SPH*0.8863} ед. здоровья и обжигает противников, нанося им от ${$85044m1+$SPH*1.2} до ${$85044M1+$SPH*1.2} ед. урона.', `AuraDescription_Lang_frFR` = 'Ein Ring aus Licht breitet sich aus und zieht sich dann wieder zusammen: Jeder Durchgang heilt Verbündete um ${$85045m1+$SPH*0.8863} und versengt Feinde für ${$85044m1+$SPH*1.2} bis ${$85044M1+$SPH*1.2} Schaden.', `AuraDescription_Lang_zhCN` = 'Un anillo de luz se expande y luego se contrae: cada pasada sana ${$85045m1+$SPH*0.8863} p. a los aliados y abrasa a los enemigos, a los que inflige de ${$85044m1+$SPH*1.2} a ${$85044M1+$SPH*1.2} p. de daño.', `AuraDescription_Lang_zhTW` = 'Кольцо света расходится во все стороны, а затем сжимается обратно: при каждом прохождении оно восстанавливает союзникам ${$85045m1+$SPH*0.8863} ед. здоровья и обжигает противников, нанося им от ${$85044m1+$SPH*1.2} до ${$85044M1+$SPH*1.2} ед. урона.' WHERE `ID` = 85043;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Todestunnel', `Name_Lang_zhCN` = 'Túnel de la muerte', `Name_Lang_zhTW` = 'Туннель смерти', `Description_Lang_frFR` = 'Errichtet eine Tür zu Euren Füßen und eine weitere am Zielpunkt, beide für 45 Sek. Benutzt eine Tür, um zur anderen zu reisen: Sie verschwindet und die andere erhält 45 Sek. Steht bereits eine Tür, wird nur eine errichtet.', `Description_Lang_zhCN` = 'Alza una puerta a tus pies y otra en el punto seleccionado, ambas durante 45 s. Usa una puerta para viajar a la otra: desaparece y la otra gana 45 s. Si ya hay una puerta alzada, solo se alza una.', `Description_Lang_zhTW` = 'Создает одну дверь у ваших ног, а другую – в указанной точке, обе на 45 сек. Воспользуйтесь дверью, чтобы переместиться к другой: она исчезнет, а время существования другой увеличится на 45 сек. Если одна дверь уже существует, создается только одна.', `AuraDescription_Lang_frFR` = 'Errichtet eine Tür zu Euren Füßen und eine weitere am Zielpunkt, beide für 45 Sek. Benutzt eine Tür, um zur anderen zu reisen: Sie verschwindet und die andere erhält 45 Sek. Steht bereits eine Tür, wird nur eine errichtet.', `AuraDescription_Lang_zhCN` = 'Alza una puerta a tus pies y otra en el punto seleccionado, ambas durante 45 s. Usa una puerta para viajar a la otra: desaparece y la otra gana 45 s. Si ya hay una puerta alzada, solo se alza una.', `AuraDescription_Lang_zhTW` = 'Создает одну дверь у ваших ног, а другую – в указанной точке, обе на 45 сек. Воспользуйтесь дверью, чтобы переместиться к другой: она исчезнет, а время существования другой увеличится на 45 сек. Если одна дверь уже существует, создается только одна.' WHERE `ID` = 85050;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Apokalypse', `Name_Lang_zhCN` = 'Apocalipsis', `Name_Lang_zhTW` = 'Конец света', `Description_Lang_frFR` = 'Lässt Eure Krankheiten auf dem Ziel platzen: ${$m1+$SPS*0.8863+$AP*0.2475} Schaden, um die Hälfte mehr pro Krankheit, und halb so viel bei Feinden innerhalb von 8 Metern. Erweckt $d lang unter jedem von ihnen einen Ghul (mindestens zwei).', `Description_Lang_zhCN` = 'Hace estallar tus enfermedades en el objetivo: ${$m1+$SPS*0.8863+$AP*0.2475} p. de daño, un 50% más por cada enfermedad, y la mitad a los enemigos en un radio de 8 m. Levanta un necrófago bajo cada uno de ellos (dos como mínimo) durante $d.', `Description_Lang_zhTW` = 'Взрывает ваши болезни на цели: ${$m1+$SPS*0.8863+$AP*0.2475} ед. урона, увеличенного наполовину за каждую болезнь, и вдвое меньше противникам в радиусе 8 м. Под каждым из них на $d. поднимается вурдалак (всего не менее двух).', `AuraDescription_Lang_frFR` = 'Lässt Eure Krankheiten auf dem Ziel platzen: ${$m1+$SPS*0.8863+$AP*0.2475} Schaden, um die Hälfte mehr pro Krankheit, und halb so viel bei Feinden innerhalb von 8 Metern. Erweckt $d lang unter jedem von ihnen einen Ghul (mindestens zwei).', `AuraDescription_Lang_zhCN` = 'Hace estallar tus enfermedades en el objetivo: ${$m1+$SPS*0.8863+$AP*0.2475} p. de daño, un 50% más por cada enfermedad, y la mitad a los enemigos en un radio de 8 m. Levanta un necrófago bajo cada uno de ellos (dos como mínimo) durante $d.', `AuraDescription_Lang_zhTW` = 'Взрывает ваши болезни на цели: ${$m1+$SPS*0.8863+$AP*0.2475} ед. урона, увеличенного наполовину за каждую болезнь, и вдвое меньше противникам в радиусе 8 м. Под каждым из них на $d. поднимается вурдалак (всего не менее двух).' WHERE `ID` = 85051;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Knochensturm', `Name_Lang_zhCN` = 'Tormenta de huesos', `Name_Lang_zhTW` = 'Буря костей', `Description_Lang_frFR` = 'Ein Sturm aus Knochen wirbelt $d lang um Euch herum, zerfetzt jede Sekunde Feinde innerhalb von 5 Metern für ${$m1+$SPS*0.495+$AP*0.0715} Schaden und heilt Euch pro darin gefangenem Feind um $s2% Eurer maximalen Gesundheit.', `Description_Lang_zhCN` = 'Una tormenta de huesos gira a tu alrededor durante $d, desgarra a los enemigos en un radio de 5 m y les inflige ${$m1+$SPS*0.495+$AP*0.0715} p. de daño cada segundo, y te restaura un $s2% de tu salud máxima por cada enemigo atrapado en ella.', `Description_Lang_zhTW` = 'В течение $d. вокруг вас кружится буря костей: каждую секунду она терзает противников в радиусе 5 м, нанося им ${$m1+$SPS*0.495+$AP*0.0715} ед. урона, и восстанавливает вам $s2% от максимального запаса здоровья за каждого задетого противника.', `AuraDescription_Lang_frFR` = 'Ein Sturm aus Knochen wirbelt um Euch herum.', `AuraDescription_Lang_zhCN` = 'Una tormenta de huesos gira a tu alrededor.', `AuraDescription_Lang_zhTW` = 'Вокруг вас кружится буря костей.' WHERE `ID` = 85052;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Sindragosas Hauch', `Name_Lang_zhCN` = 'Aliento de Sindragosa', `Name_Lang_zhTW` = 'Дыхание Синдрагосы', `Description_Lang_frFR` = 'Stößt einen eisigen Hauch aus, der jede Sekunde ${$85054m1+$AP*0.45} bis ${$85054M1+$AP*0.45} Schaden verursacht, solange die Runenmacht reicht.', `Description_Lang_zhCN` = 'Exhala un aliento gélido que inflige de ${$85054m1+$AP*0.45} a ${$85054M1+$AP*0.45} p. de daño cada segundo mientras dure el poder rúnico.', `Description_Lang_zhTW` = 'Вы испускаете леденящее дыхание, наносящее от ${$85054m1+$AP*0.45} до ${$85054M1+$AP*0.45} ед. урона каждую секунду, пока не иссякнет сила рун.', `AuraDescription_Lang_frFR` = 'Stößt einen eisigen Hauch aus.', `AuraDescription_Lang_zhCN` = 'Exhalando un aliento gélido.', `AuraDescription_Lang_zhTW` = 'Вы испускаете леденящее дыхание.' WHERE `ID` = 85053;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Sindragosas Hauch (Tick)', `Name_Lang_zhCN` = 'Aliento de Sindragosa (pulso)', `Name_Lang_zhTW` = 'Дыхание Синдрагосы (такт)', `Description_Lang_frFR` = 'Eisiger Hauch.', `Description_Lang_zhCN` = 'Aliento gélido.', `Description_Lang_zhTW` = 'Леденящее дыхание.', `AuraDescription_Lang_frFR` = 'Eisiger Hauch.', `AuraDescription_Lang_zhCN` = 'Aliento gélido.', `AuraDescription_Lang_zhTW` = 'Леденящее дыхание.' WHERE `ID` = 85054;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Geistverbindung', `Name_Lang_zhCN` = 'Vínculo de espíritu', `Name_Lang_zhTW` = 'Духовная связь', `Description_Lang_frFR` = 'Eure Gesundheit wird mit Gruppenmitgliedern in der Nähe geteilt. Heilt jede Sekunde $s1% der maximalen Gesundheit, erlittener Schaden um 3% verringert.', `Description_Lang_zhCN` = 'Tu salud se comparte con los miembros del grupo cercanos. Te sanas un $s1% de la salud máxima cada segundo y el daño recibido se reduce un 3%.', `Description_Lang_zhTW` = 'Ваше здоровье объединено со здоровьем находящихся поблизости участников группы. Каждую секунду вы восстанавливаете $s1% от максимального запаса здоровья, а получаемый урон снижен на 3%.', `AuraDescription_Lang_frFR` = 'Gesundheit mit der Gruppe geteilt. Heilt $s1% pro Sekunde, erlittener Schaden um 3% verringert.', `AuraDescription_Lang_zhCN` = 'Salud compartida con el grupo. Sanación de un $s1% por segundo; daño recibido reducido un 3%.', `AuraDescription_Lang_zhTW` = 'Здоровье объединено с группой. Восстановление $s1% здоровья в секунду, получаемый урон снижен на 3%.' WHERE `ID` = 85064;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Totem der Geistverbindung', `Name_Lang_zhCN` = 'Tótem de vínculo de espíritu', `Name_Lang_zhTW` = 'Тотем духовной связи' WHERE `ID` = 85069;
