UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Windstoß', `Name_Lang_zhCN` = 'Racha de viento', `Name_Lang_zhTW` = 'Порыв ветра', `Description_Lang_frFR` = 'Der Wind schleudert Euch in Eure Bewegungsrichtung.', `Description_Lang_zhCN` = 'El viento te impulsa en la dirección en la que te mueves.', `Description_Lang_zhTW` = 'Ветер бросает вас в направлении вашего движения.', `AuraDescription_Lang_frFR` = 'Der Wind schleudert Euch in Eure Bewegungsrichtung.', `AuraDescription_Lang_zhCN` = 'El viento te impulsa en la dirección en la que te mueves.', `AuraDescription_Lang_zhTW` = 'Ветер бросает вас в направлении вашего движения.' WHERE `ID` = 85060;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Erdbeben', `Name_Lang_zhCN` = 'Terremoto', `Name_Lang_zhTW` = 'Землетрясение', `Description_Lang_frFR` = 'Erschüttert $d lang den Boden: ${$m1+$SPH*0.4864+$AP*0.1886} Schaden pro Sekunde, mit einer Chance, die Opfer umzuwerfen.', `Description_Lang_zhCN` = 'Sacude el suelo durante $d: ${$m1+$SPH*0.4864+$AP*0.1886} p. de daño cada segundo, con probabilidad de derribar a las víctimas.', `Description_Lang_zhTW` = 'В течение $d. сотрясает землю: ${$m1+$SPH*0.4864+$AP*0.1886} ед. урона каждую секунду с вероятностью сбить жертв с ног.', `AuraDescription_Lang_frFR` = 'Erschüttert $d lang den Boden: ${$m1+$SPH*0.4864+$AP*0.1886} Schaden pro Sekunde, mit einer Chance, die Opfer umzuwerfen.', `AuraDescription_Lang_zhCN` = 'Sacude el suelo durante $d: ${$m1+$SPH*0.4864+$AP*0.1886} p. de daño cada segundo, con probabilidad de derribar a las víctimas.', `AuraDescription_Lang_zhTW` = 'В течение $d. сотрясает землю: ${$m1+$SPH*0.4864+$AP*0.1886} ед. урона каждую секунду с вероятностью сбить жертв с ног.' WHERE `ID` = 85061;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Überlegenheit', `Name_Lang_zhCN` = 'Ascensión', `Name_Lang_zhTW` = 'Господство', `Description_Lang_frFR` = 'Euer Magieschaden ist $d lang um $s1% erhöht. Jeder Feuerzauber, den Ihr wirkt, erhöht Eure kritische Trefferchance um 3% und jeder Naturzauber Euer Tempo um 3%; die Effekte sind bis zum Ende von ''Überlegenheit'' stapelbar. Zusätzlich werden fünf Feinde vor Euch von ''Flammenschock'' und anschließend von ''Lavaexplosion'' getroffen. ''Blitzschlag'', ''Kettenblitzschlag'' und ''Lavaexplosion'' werden sofort gewirkt.', `Description_Lang_zhCN` = 'Tu daño mágico aumenta un $s1% durante $d. Cada hechizo de Fuego que lanzas aumenta tu probabilidad de golpe crítico un 3% y cada hechizo de Naturaleza, tu celeridad un 3%, de forma acumulable hasta que termina Ascensión. Además, cinco enemigos delante de ti reciben un Choque de llamas seguido de una Ráfaga de lava. Descarga de relámpagos, Cadena de relámpagos y Ráfaga de lava pasan a ser instantáneos.', `Description_Lang_zhTW` = 'Наносимый вами урон от магии увеличивается на $s1% на $d. Каждое произнесенное заклинание огня повышает вероятность критического удара на 3%, а каждое заклинание сил природы – скорость на 3%. Эти эффекты суммируются до окончания действия "Господства". Кроме того, пять противников перед вами поражаются "Огненным шоком", а затем "Выбросом лавы". Заклинания "Молния", "Цепная молния" и "Выброс лавы" применяются мгновенно.', `AuraDescription_Lang_frFR` = 'Magieschaden um $s1% erhöht. Feuerzauber erhöhen die kritische Trefferchance, Naturzauber das Tempo. ''Blitzschlag'', ''Kettenblitzschlag'' und ''Lavaexplosion'' werden sofort gewirkt.', `AuraDescription_Lang_zhCN` = 'Daño mágico aumentado un $s1%. Los hechizos de Fuego aumentan la probabilidad de golpe crítico y los de Naturaleza, la celeridad. Descarga de relámpagos, Cadena de relámpagos y Ráfaga de lava pasan a ser instantáneos.', `AuraDescription_Lang_zhTW` = 'Урон от магии увеличен на $s1%. Заклинания огня повышают вероятность критического удара, заклинания сил природы – скорость. Заклинания "Молния", "Цепная молния" и "Выброс лавы" применяются мгновенно.' WHERE `ID` = 85062;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Totem der Geistverbindung', `Name_Lang_zhCN` = 'Tótem de vínculo de espíritu', `Name_Lang_zhTW` = 'Тотем духовной связи', `Description_Lang_frFR` = 'Beschwört $d lang ein Totem. Jede Sekunde heilt es Euch und alle Gruppen- oder Schlachtzugsmitglieder innerhalb von 7 Metern um 2% der maximalen Gesundheit, und alle Betroffenen erleiden 3% weniger Schaden. Sind andere anwesend, wird zudem die Gesundheit umverteilt: Wer über dem Median liegt, gibt bis zu 10% seiner aktuellen Gesundheit an jene darunter ab, im Verhältnis zu dem, was ihnen fehlt.', `Description_Lang_zhCN` = 'Invoca un tótem durante $d. Cada segundo, tú y los miembros del grupo o banda en un radio de 7 m recuperáis un 2% de la salud máxima y recibís un 3% menos de daño. Si hay más personas presentes, la salud también se redistribuye: quienes están por encima de la mediana ceden hasta un 10% de su salud actual a quienes están por debajo, en proporción a lo que les falta.', `Description_Lang_zhTW` = 'Призывает тотем на $d. Каждую секунду вы и участники группы или рейда в радиусе 7 м восстанавливаете 2% от максимального запаса здоровья и получаете на 3% меньше урона. Если рядом есть другие персонажи, здоровье также перераспределяется: те, у кого его больше медианного значения, отдают до 10% своего текущего здоровья тем, у кого его меньше, пропорционально недостающему им здоровью.', `AuraDescription_Lang_frFR` = 'Die Gesundheit wird unter Gruppenmitgliedern in der Nähe umverteilt.', `AuraDescription_Lang_zhCN` = 'La salud se está redistribuyendo entre los miembros del grupo cercanos.', `AuraDescription_Lang_zhTW` = 'Здоровье перераспределяется между находящимися поблизости участниками группы.' WHERE `ID` = 85063;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Schimmern', `Name_Lang_zhCN` = 'Centelleo', `Name_Lang_zhTW` = 'Мерцание', `Description_Lang_frFR` = 'Ihr schimmert in Eure Bewegungsrichtung und hinterlasst eine Markierung. Wirkt den Zauber innerhalb von $85058d erneut, um zu ihr zurückzukehren.', `Description_Lang_zhCN` = 'Centelleas en la dirección en la que te mueves y dejas una marca atrás. Vuelve a lanzarlo en menos de $85058d para regresar a ella.', `Description_Lang_zhTW` = 'Вы совершаете мерцание в направлении движения, оставляя за собой метку. Примените заклинание повторно в течение $85058d., чтобы вернуться к ней.', `AuraDescription_Lang_frFR` = 'Ihr schimmert in Eure Bewegungsrichtung und hinterlasst eine Markierung. Wirkt den Zauber innerhalb von $85058d erneut, um zu ihr zurückzukehren.', `AuraDescription_Lang_zhCN` = 'Centelleas en la dirección en la que te mueves y dejas una marca atrás. Vuelve a lanzarlo en menos de $85058d para regresar a ella.', `AuraDescription_Lang_zhTW` = 'Вы совершаете мерцание в направлении движения, оставляя за собой метку. Примените заклинание повторно в течение $85058d., чтобы вернуться к ней.' WHERE `ID` = 85070;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Arkane Kugel', `Name_Lang_zhCN` = 'Orbe Arcano', `Name_Lang_zhTW` = 'Чародейский шар', `Description_Lang_frFR` = 'Entsendet eine Kugel, die alles auf ihrem Weg für ${$m1+$SPH*0.7854} Schaden trifft.', `Description_Lang_zhCN` = 'Envía un orbe que golpea todo lo que encuentra a su paso y le inflige ${$m1+$SPH*0.7854} p. de daño.', `Description_Lang_zhTW` = 'Выпускает шар, который наносит ${$m1+$SPH*0.7854} ед. урона всем на своем пути.', `AuraDescription_Lang_frFR` = 'Entsendet eine Kugel, die alles auf ihrem Weg für ${$m1+$SPH*0.7854} Schaden trifft.', `AuraDescription_Lang_zhCN` = 'Envía un orbe que golpea todo lo que encuentra a su paso y le inflige ${$m1+$SPH*0.7854} p. de daño.', `AuraDescription_Lang_zhTW` = 'Выпускает шар, который наносит ${$m1+$SPH*0.7854} ед. урона всем на своем пути.' WHERE `ID` = 85071;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Meteor', `Name_Lang_zhCN` = 'Meteorito', `Name_Lang_zhTW` = 'Метеор', `Description_Lang_frFR` = 'Ruft einen Meteor herbei, der mit ${$m1+$SPH*0.3948} Schaden einschlägt und den Boden $d lang brennen lässt.', `Description_Lang_zhCN` = 'Invoca un meteorito que inflige ${$m1+$SPH*0.3948} p. de daño al impactar y deja el suelo en llamas durante $d.', `Description_Lang_zhTW` = 'Призывает метеор, который наносит ${$m1+$SPH*0.3948} ед. урона и поджигает землю на $d.', `AuraDescription_Lang_frFR` = 'Ruft einen Meteor herbei, der mit ${$m1+$SPH*0.3948} Schaden einschlägt und den Boden $d lang brennen lässt.', `AuraDescription_Lang_zhCN` = 'Invoca un meteorito que inflige ${$m1+$SPH*0.3948} p. de daño al impactar y deja el suelo en llamas durante $d.', `AuraDescription_Lang_zhTW` = 'Призывает метеор, который наносит ${$m1+$SPH*0.3948} ед. урона и поджигает землю на $d.' WHERE `ID` = 85072;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Frostrahl', `Name_Lang_zhCN` = 'Rayo de Escarcha', `Name_Lang_zhTW` = 'Морозный луч', `Description_Lang_frFR` = 'Kanalisiert $d lang einen Frostrahl auf das Ziel, der pro Sekunde ${$m1+$SPH*0.175} Schaden verursacht und mit jeder Sekunde stärker wird.', `Description_Lang_zhCN` = 'Canaliza un rayo de escarcha sobre el objetivo durante $d que inflige ${$m1+$SPH*0.175} p. de daño por segundo, cantidad que aumenta cada segundo.', `Description_Lang_zhTW` = 'В течение $d. направляет на цель морозный луч, наносящий ${$m1+$SPH*0.175} ед. урона в секунду. Урон возрастает с каждой секундой.', `AuraDescription_Lang_frFR` = 'Kanalisiert $d lang einen Frostrahl auf das Ziel, der pro Sekunde ${$m1+$SPH*0.175} Schaden verursacht und mit jeder Sekunde stärker wird.', `AuraDescription_Lang_zhCN` = 'Canaliza un rayo de escarcha sobre el objetivo durante $d que inflige ${$m1+$SPH*0.175} p. de daño por segundo, cantidad que aumenta cada segundo.', `AuraDescription_Lang_zhTW` = 'В течение $d. направляет на цель морозный луч, наносящий ${$m1+$SPH*0.175} ед. урона в секунду. Урон возрастает с каждой секундой.' WHERE `ID` = 85073;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Brennender Ansturm', `Name_Lang_zhCN` = 'Carrera ardiente', `Name_Lang_zhTW` = 'Пылающий рывок', `Description_Lang_frFR` = 'Euer Tempo erhöht sich um $s1%, verbrennt jedoch jede Sekunde $s2% Eurer maximalen Gesundheit, bis Ihr den Zauber erneut wirkt. Der Effekt endet von selbst, bevor er Euch töten kann, und erfordert zum Wirken mehr als 16% Gesundheit.', `Description_Lang_zhCN` = 'Tu velocidad aumenta un $s1% a cambio de quemar un $s2% de tu salud máxima cada segundo, hasta que lo vuelvas a lanzar. Termina por sí solo antes de poder matarte y requiere más de un 16% de salud para lanzarse.', `Description_Lang_zhTW` = 'Ваша скорость передвижения повышается на $s1%, но каждую секунду вы теряете $s2% от максимального запаса здоровья, пока не примените заклинание повторно. Эффект прекращается сам, прежде чем убить вас. Для применения требуется более 16% здоровья.', `AuraDescription_Lang_frFR` = 'Euer Tempo erhöht sich um $s1%, verbrennt jedoch jede Sekunde $s2% Eurer maximalen Gesundheit, bis Ihr den Zauber erneut wirkt. Der Effekt endet von selbst, bevor er Euch töten kann, und erfordert zum Wirken mehr als 16% Gesundheit.', `AuraDescription_Lang_zhCN` = 'Tu velocidad aumenta un $s1% a cambio de quemar un $s2% de tu salud máxima cada segundo, hasta que lo vuelvas a lanzar. Termina por sí solo antes de poder matarte y requiere más de un 16% de salud para lanzarse.', `AuraDescription_Lang_zhTW` = 'Ваша скорость передвижения повышается на $s1%, но каждую секунду вы теряете $s2% от максимального запаса здоровья, пока не примените заклинание повторно. Эффект прекращается сам, прежде чем убить вас. Для применения требуется более 16% здоровья.' WHERE `ID` = 85080;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Phantomsingularität', `Name_Lang_zhCN` = 'Singularidad fantasma', `Name_Lang_zhTW` = 'Призрачная сингулярность', `Description_Lang_frFR` = 'Eine Singularität saugt jede Sekunde alle Feinde unter ihr für ${$m1+$SPS*0.1045} bis ${$M1+$SPS*0.1045} aus.', `Description_Lang_zhCN` = 'Una singularidad drena de ${$m1+$SPS*0.1045} a ${$M1+$SPS*0.1045} p. cada segundo a todos los enemigos que se encuentran debajo.', `Description_Lang_zhTW` = 'Сингулярность каждую секунду вытягивает из всех противников под ней от ${$m1+$SPS*0.1045} до ${$M1+$SPS*0.1045} ед. здоровья.', `AuraDescription_Lang_frFR` = 'Eine Singularität saugt jede Sekunde alle Feinde unter ihr für ${$m1+$SPS*0.1045} bis ${$M1+$SPS*0.1045} aus.', `AuraDescription_Lang_zhCN` = 'Una singularidad drena de ${$m1+$SPS*0.1045} a ${$M1+$SPS*0.1045} p. cada segundo a todos los enemigos que se encuentran debajo.', `AuraDescription_Lang_zhTW` = 'Сингулярность каждую секунду вытягивает из всех противников под ней от ${$m1+$SPS*0.1045} до ${$M1+$SPS*0.1045} ед. здоровья.' WHERE `ID` = 85081;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Dämonischen Tyrannen beschwören', `Name_Lang_zhCN` = 'Invocar tirano demoníaco', `Name_Lang_zhTW` = 'Призыв демонического тирана', `Description_Lang_frFR` = 'Ruft $d lang einen dämonischen Tyrannen herbei, der jeden Dämon unter Eurem Befehl stärkt.', `Description_Lang_zhCN` = 'Llama a un tirano demoníaco durante $d que fortalece a todos los demonios bajo tu mando.', `Description_Lang_zhTW` = 'Призывает демонического тирана на $d. Тиран усиливает всех демонов под вашим командованием.', `AuraDescription_Lang_frFR` = 'Ruft $d lang einen dämonischen Tyrannen herbei, der jeden Dämon unter Eurem Befehl stärkt.', `AuraDescription_Lang_zhCN` = 'Llama a un tirano demoníaco durante $d que fortalece a todos los demonios bajo tu mando.', `AuraDescription_Lang_zhTW` = 'Призывает демонического тирана на $d. Тиран усиливает всех демонов под вашим командованием.' WHERE `ID` = 85082;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Katastrophe', `Name_Lang_zhCN` = 'Cataclismo', `Name_Lang_zhTW` = 'Катаклизм', `Description_Lang_frFR` = 'Verbraucht einen Seelensplitter, um Euer Ziel für ${$m1+$SPH*0.55} bis ${$M1+$SPH*0.55} Schaden zu treffen und alle Feinde innerhalb von $a3 Metern in Brand zu setzen. Euer Schaden erhöht sich $d lang um $s2%, und Eure nächsten beiden Zauber ''Seelenfeuer'' oder ''Chaosblitz'' werden sofort gewirkt.', `Description_Lang_zhCN` = 'Consume un fragmento de alma para golpear a tu objetivo, al que inflige de ${$m1+$SPH*0.55} a ${$M1+$SPH*0.55} p. de daño, y prende fuego a todos los enemigos en un radio de $a3 m. Tu daño aumenta un $s2% durante $d y tus dos siguientes lanzamientos de Fuego de alma o Descarga de caos pasan a ser instantáneos.', `Description_Lang_zhTW` = 'Поглощает осколок души, чтобы нанести цели от ${$m1+$SPH*0.55} до ${$M1+$SPH*0.55} ед. урона и поджечь всех противников в радиусе $a3 м. Наносимый вами урон увеличивается на $s2% на $d., а два следующих заклинания "Ожог души" или "Стрела Хаоса" применяются мгновенно.', `AuraDescription_Lang_frFR` = 'Schaden um $s2% erhöht.', `AuraDescription_Lang_zhCN` = 'Daño aumentado un $s2%.', `AuraDescription_Lang_zhTW` = 'Увеличение урона на $s2%.' WHERE `ID` = 85083;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Dämonische Macht: Wichtel', `Name_Lang_zhCN` = 'Poder demoníaco: diablillo', `Name_Lang_zhTW` = 'Демоническая сила: бес', `AuraDescription_Lang_frFR` = 'Zaubertempo um $s1% erhöht.', `AuraDescription_Lang_zhCN` = 'Velocidad de lanzamiento aumentada un $s1%.', `AuraDescription_Lang_zhTW` = 'Скорость применения заклинаний повышена на $s1%.' WHERE `ID` = 85100;
