UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Dämonische Macht: Leerwandler', `Name_Lang_zhCN` = 'Poder demoníaco: abisario', `Name_Lang_zhTW` = 'Демоническая сила: демон Бездны', `AuraDescription_Lang_frFR` = 'Bedrohung um $s1% erhöht und von einem Schild in Höhe der Hälfte seiner maximalen Gesundheit geschützt.', `AuraDescription_Lang_zhCN` = 'Amenaza aumentada un $s1% y protegido por un escudo equivalente a la mitad de su salud máxima.', `AuraDescription_Lang_zhTW` = 'Создаваемая угроза увеличена на $s1%. Существо защищено щитом, равным половине его максимального запаса здоровья.' WHERE `ID` = 85103;
