UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Zorn des Schläfers', `Name_Lang_zhCN` = 'Ira del Durmiente', `Name_Lang_zhTW` = 'Ярость Спящего', `Description_Lang_frFR` = 'Ihr erleidet $d lang $s1% weniger Schaden. Jeder Nahkampftreffer, den Ihr erleidet, fügt dem Angreifer ${$m2+$AP*0.03} Naturschaden zu und heilt Euch um $s3% davon.', `Description_Lang_zhCN` = 'Recibes un $s1% menos de daño durante $d. Cada golpe cuerpo a cuerpo que recibes inflige ${$m2+$AP*0.03} p. de daño de Naturaleza al atacante y te sana un $s3% de esa cantidad.', `Description_Lang_zhTW` = 'Получаемый вами урон снижается на $s1% на $d. Каждый пропущенный вами удар в ближнем бою наносит атакующему ${$m2+$AP*0.03} ед. урона от сил природы и восстанавливает вам здоровье в объеме $s3% от этого урона.', `AuraDescription_Lang_frFR` = 'Erleidet $s1% weniger Schaden; Nahkampfangreifer erleiden ${$m2+$AP*0.03} Naturschaden.', `AuraDescription_Lang_zhCN` = 'Recibe un $s1% menos de daño; los atacantes cuerpo a cuerpo reciben ${$m2+$AP*0.03} p. de daño de Naturaleza.', `AuraDescription_Lang_zhTW` = 'Получаемый урон снижен на $s1%. Атакующие в ближнем бою получают ${$m2+$AP*0.03} ед. урона от сил природы.' WHERE `ID` = 85137;
