UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Leichter Schritt', `Name_Lang_zhCN` = 'Zancada ligera', `Name_Lang_zhTW` = 'Легкая поступь', `Description_Lang_frFR` = 'Erhöht das Bewegungstempo $d lang um $s1%. Nur in humanoider Gestalt: In einer anderen Gestalt gewirkt, versetzt es Euch zuerst in die humanoide Gestalt zurück.', `Description_Lang_zhCN` = 'Aumenta la velocidad de movimiento un $s1% durante $d. Solo en forma humanoide: si se lanza en cualquier otra forma, primero te devuelve a la forma humanoide.', `Description_Lang_zhTW` = 'Повышает скорость передвижения на $s1% на $d. Действует только в облике гуманоида: если применить заклинание в другом облике, оно сначала вернет вас в облик гуманоида.', `AuraDescription_Lang_frFR` = 'Bewegungstempo um $s1% erhöht.', `AuraDescription_Lang_zhCN` = 'Velocidad de movimiento aumentada un $s1%.', `AuraDescription_Lang_zhTW` = 'Скорость передвижения повышена на $s1%.' WHERE `ID` = 85090;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Wilde Raserei', `Name_Lang_zhCN` = 'Frenesí feral', `Name_Lang_zhTW` = 'Звериное бешенство', `Description_Lang_frFR` = 'Finishing Move, der pro Combopunkt Schaden verursacht und das Ziel anschließend 6 Sek. lang bluten lässt. Bei 5 Punkten ist Eure nächste Fähigkeit ein kritischer Treffer:\n\n    1 Punkt  : ${700+$AP*0.7558} Schaden.\n    2 Punkte: ${800+$AP*0.7558} Schaden, ${120+$AP*0.166} pro Sek.\n    3 Punkte: ${1000+$AP*0.7558} Schaden, ${160+$AP*0.166} pro Sek., 5% Tempo.\n    4 Punkte: ${1100+$AP*0.7558} Schaden, ${200+$AP*0.166} pro Sek., 7% Tempo, 10 Energie.\n    5 Punkte: ${1200+$AP*0.7558} Schaden, ${240+$AP*0.166} pro Sek., 10% Tempo, 15 Energie.', `Description_Lang_zhCN` = 'Movimiento final que inflige daño por cada punto de combo y después provoca un sangrado durante 6 s. Con 5 puntos, tu siguiente facultad será un golpe crítico:\n\n    1 punto: ${700+$AP*0.7558} p. de daño.\n    2 puntos: ${800+$AP*0.7558} p. de daño, ${120+$AP*0.166} p. por segundo.\n    3 puntos: ${1000+$AP*0.7558} p. de daño, ${160+$AP*0.166} p. por segundo, 5% de celeridad.\n    4 puntos: ${1100+$AP*0.7558} p. de daño, ${200+$AP*0.166} p. por segundo, 7% de celeridad, 10 p. de energía.\n    5 puntos: ${1200+$AP*0.7558} p. de daño, ${240+$AP*0.166} p. por segundo, 10% de celeridad, 15 p. de energía.', `Description_Lang_zhTW` = 'Завершающий прием, урон которого зависит от длины серии приемов, после чего цель истекает кровью в течение 6 сек. При серии из 5 приемов ваша следующая способность нанесет критический удар:\n\n    1 прием: ${700+$AP*0.7558} ед. урона.\n    2 приема: ${800+$AP*0.7558} ед. урона, ${120+$AP*0.166} ед. в сек.\n    3 приема: ${1000+$AP*0.7558} ед. урона, ${160+$AP*0.166} ед. в сек., скорость +5%.\n    4 приема: ${1100+$AP*0.7558} ед. урона, ${200+$AP*0.166} ед. в сек., скорость +7%, 10 ед. энергии.\n    5 приемов: ${1200+$AP*0.7558} ед. урона, ${240+$AP*0.166} ед. в сек., скорость +10%, 15 ед. энергии.', `AuraDescription_Lang_frFR` = 'Finishing Move, der pro Combopunkt Schaden verursacht und das Ziel anschließend 6 Sek. lang bluten lässt. Bei 5 Punkten ist Eure nächste Fähigkeit ein kritischer Treffer:\n\n    1 Punkt  : ${700+$AP*0.7558} Schaden.\n    2 Punkte: ${800+$AP*0.7558} Schaden, ${120+$AP*0.166} pro Sek.\n    3 Punkte: ${1000+$AP*0.7558} Schaden, ${160+$AP*0.166} pro Sek., 5% Tempo.\n    4 Punkte: ${1100+$AP*0.7558} Schaden, ${200+$AP*0.166} pro Sek., 7% Tempo, 10 Energie.\n    5 Punkte: ${1200+$AP*0.7558} Schaden, ${240+$AP*0.166} pro Sek., 10% Tempo, 15 Energie.' WHERE `ID` = 85091;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Sonnenwende und Tagundnachtgleiche', `Name_Lang_zhCN` = 'Solsticio y Equinoccio', `Name_Lang_zhTW` = 'Солнцестояние и равноденствие', `Description_Lang_frFR` = 'Trifft für ${$m1+$SPH*1.2} bis ${$M1+$SPH*1.2} Arkanschaden. Nur in den wenigen Sekunden verwendbar, nachdem Eure Himmelsleiste eines ihrer Enden erreicht hat.', `Description_Lang_zhCN` = 'Golpea e inflige de ${$m1+$SPH*1.2} a ${$M1+$SPH*1.2} p. de daño Arcano. Solo se puede usar durante los pocos segundos que siguen a cada vez que tu indicador celestial alcanza uno de sus extremos.', `Description_Lang_zhTW` = 'Наносит от ${$m1+$SPH*1.2} до ${$M1+$SPH*1.2} ед. урона от тайной магии. Можно использовать только в течение нескольких секунд после того, как ваша небесная шкала достигает одного из своих концов.', `AuraDescription_Lang_frFR` = 'Trifft für ${$m1+$SPH*1.2} bis ${$M1+$SPH*1.2} Arkanschaden. Nur in den wenigen Sekunden verwendbar, nachdem Eure Himmelsleiste eines ihrer Enden erreicht hat.', `AuraDescription_Lang_zhCN` = 'Golpea e inflige de ${$m1+$SPH*1.2} a ${$M1+$SPH*1.2} p. de daño Arcano. Solo se puede usar durante los pocos segundos que siguen a cada vez que tu indicador celestial alcanza uno de sus extremos.', `AuraDescription_Lang_zhTW` = 'Наносит от ${$m1+$SPH*1.2} до ${$M1+$SPH*1.2} ед. урона от тайной магии. Можно использовать только в течение нескольких секунд после того, как ваша небесная шкала достигает одного из своих концов.' WHERE `ID` = 85092;
UPDATE `spell_dbc` SET `Name_Lang_frFR` = 'Gedeihen', `Name_Lang_zhCN` = 'Florecer', `Name_Lang_zhTW` = 'Расцвет', `Description_Lang_frFR` = 'Jeder Effekt mit Heilung über Zeit auf dem Ziel wird auf seine volle Dauer zurückgesetzt, und zu seinen Füßen öffnet sich eine heilende Blüte.', `Description_Lang_zhCN` = 'Todos los efectos de sanación en el tiempo del objetivo recuperan su duración completa y una flor sanadora se abre a sus pies.', `Description_Lang_zhTW` = 'Время действия всех эффектов периодического исцеления на цели восстанавливается до полного, а у ее ног распускается исцеляющий цветок.', `AuraDescription_Lang_frFR` = 'Jeder Effekt mit Heilung über Zeit auf dem Ziel wird auf seine volle Dauer zurückgesetzt, und zu seinen Füßen öffnet sich eine heilende Blüte.', `AuraDescription_Lang_zhCN` = 'Todos los efectos de sanación en el tiempo del objetivo recuperan su duración completa y una flor sanadora se abre a sus pies.', `AuraDescription_Lang_zhTW` = 'Время действия всех эффектов периодического исцеления на цели восстанавливается до полного, а у ее ног распускается исцеляющий цветок.' WHERE `ID` = 85093;
